import { TtsExtension, TtsManager } from "#core/ui/accessibility/tts-manager.js";
import TooltipManager from "#core/ui/tooltips/tooltip-manager.js";

export class TtsManagerTooltipExtension implements TtsExtension {
	private getActiveTooltip(self: typeof TtsManager, addText: (text: string) => void): boolean {
		const curTooltip = TooltipManager.currentTooltip;

		if (curTooltip) {
			addText(self.getElementInnerText(curTooltip));
			return true;
		}

		return false;
	}

	public checkGlobal(self: typeof TtsManager, addText: (text: string) => void): boolean {
		// Check if a global tooltip is active (usually world tile tooltips)
		return this.getActiveTooltip(self, addText);
	}

	public checkElement(self: typeof TtsManager, element: Element, addText: (text: string) => void): boolean {
		// Check if an element specific tooltip is active
		if (element.hasAttribute("data-tooltip-style")) {
			return this.getActiveTooltip(self, addText);
		}

		return false;
	}
}
